Section WithSegs.
Variable segs : list Segment. Context {bmK : BMode}.   (* [comment removed for export] *)

Definition cells_at (m : word -> option byte) (A : Z) (cs : list cell) : Prop :=
  cells_wf cs /\ bytes_at segs m A (cells_bytes cs).

